package com.certmanage.sync;

import com.certmanage.common.*;
import com.certmanage.server.ServerService;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import org.springframework.scheduling.support.CronExpression;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.time.*;
import java.util.*;
import static com.certmanage.common.Errors.require;
import static com.certmanage.sync.SyncData.*;

@Service
public class WorkflowService {
 private final ExecutionLog logs;private final JdbcTemplate db;private final TransactionTemplate tx;private final ObjectMapper json;private final ConfigSecrets secrets;private final Audit audit;private final WorkflowValidator validator;private final ServerService servers;
 public WorkflowService(JdbcTemplate db,TransactionTemplate tx,ObjectMapper json,ConfigSecrets secrets,Audit audit,WorkflowValidator validator,ServerService servers,ExecutionLog logs){this.db=db;this.tx=tx;this.json=json;this.secrets=secrets;this.audit=audit;this.validator=validator;this.servers=servers;this.logs=logs;}
 void lock(){db.queryForObject("select id from sync_guard where id=1 for update",Integer.class);}
 String encode(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("流程配置无法序列化");}}
 Map<String,Object> decode(String s){try{return json.readValue(s,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});}catch(Exception e){throw new IllegalStateException("流程配置无法读取");}}
 private Map<String,Object> taskRow(ResultSet r,int n)throws SQLException{var m=new LinkedHashMap<String,Object>();m.put("id",r.getLong("id"));m.put("name",r.getString("name"));m.put("description",r.getString("description"));m.put("revision",r.getLong("config_revision"));m.put("state",r.getString("state"));m.put("scheduleEnabled",r.getBoolean("schedule_enabled"));m.put("cron",r.getString("cron"));m.put("timezone",r.getString("timezone"));m.put("nextFireAt",r.getObject("next_fire_at")==null?null:r.getObject("next_fire_at",OffsetDateTime.class).toString());return m;}
 public List<Map<String,Object>> list(){var tasks=db.query("select * from sync_tasks where deleted_at is null order by id desc",this::taskRow);for(var task:tasks){var last=db.queryForList("select id,status from sync_runs where task_id=? order by id desc fetch first 1 row only",task.get("id"));task.put("lastStatus",last.isEmpty()?null:last.getFirst().get("STATUS"));}return tasks;}
 Map<String,Object> stored(long id){var rows=db.query("select * from sync_tasks where id=? and deleted_at is null",this::taskRow,id);require(!rows.isEmpty(),"同步任务不存在");var task=rows.getFirst();task.put("steps",db.query("select * from sync_task_steps where task_id=? order by position",(r,n)->{var step=new LinkedHashMap<String,Object>();step.put("key",r.getString("step_key"));step.put("name",r.getString("name"));step.put("type",r.getString("component_type"));step.put("config",decode(r.getString("config_json")));step.put("secretId",r.getObject("secret_bundle_id"));return step;},id));return task;}
 public Map<String,Object> detail(long id){var task=stored(id);var visible=new ArrayList<Map<String,Object>>();for(var step:maps(task.get("steps"))){var secret=secrets.read(step.get("secretId")==null?null:((Number)step.get("secretId")).longValue());step.remove("secretId");var c=map(step.get("config"));c.remove("references");c.remove("resolvedEntries");c.put("passwordConfigured",secret.containsKey("password"));c.put("keyPasswordConfigured",secret.containsKey("keyPassword"));step.put("config",c);visible.add(step);}task.put("steps",visible);return task;}
 public Map<String,Object> save(Long id,Map<String,Object> input,String user){return tx.execute(status->{lock();Map<String,Object> old=id==null?Map.of():stored(id);if(id!=null&&(!Objects.equals(((Number)old.get("revision")).longValue(),input.get("revision") instanceof Number n?n.longValue():-1L)))throw new ResponseStatusException(HttpStatus.CONFLICT,"配置已修改，请刷新后重试");
  String name=str(input,"name","").trim(),description=str(input,"description","");require(!name.isEmpty()&&name.length()<=200&&description.length()<=2000,"任务名称必填，名称或描述过长");String state=str(input,"state","DRAFT");require(Set.of("DRAFT","READY").contains(state),"任务状态错误");boolean enabled=Boolean.TRUE.equals(input.get("scheduleEnabled"));require(!enabled||state.equals("READY"),"草稿不能启用定时");String cron=str(input,"cron","0 0 2 * * *"),zone=str(input,"timezone","Asia/Shanghai");var next=validator.nextTimes(cron,zone);var oldByKey=new HashMap<String,Map<String,Object>>();for(var step:maps(old.get("steps")))oldByKey.put(str(step,"key",""),step);
  var steps=new ArrayList<Map<String,Object>>();for(var supplied:maps(input.get("steps"))){var step=new LinkedHashMap<String,Object>();String key=str(supplied,"key",UUID.randomUUID().toString());step.put("key",key);step.put("name",str(supplied,"name",str(supplied,"type","")));step.put("type",str(supplied,"type",""));var c=map(supplied.get("config"));var oldStep=oldByKey.get(key);Long secretId=oldStep==null||oldStep.get("secretId")==null?null:((Number)oldStep.get("secretId")).longValue();var secret=new LinkedHashMap<>(secrets.read(secretId));boolean changed=false;for(String field:List.of("password","keyPassword")){if(c.containsKey(field)){String value=str(c,field,"");if(!value.isEmpty()){secret.put(field,value);changed=true;}c.remove(field);}c.remove(field+"Configured");}if(changed)secretId=secrets.save(secret);step.put("secretId",secretId);step.put("config",c);steps.add(step);}
  validator.prepare(steps,state.equals("READY"));long actor=audit.actor(user);if(id==null){db.update("insert into sync_tasks(name,description,state,schedule_enabled,cron,timezone,next_fire_at,created_by,updated_by) values(?,?,?,?,?,?,?,?,?)",name,description,state,enabled,cron,zone,enabled?ZonedDateTime.parse(next.getFirst()).toOffsetDateTime():null,actor,actor);}else db.update("update sync_tasks set name=?,description=?,state=?,schedule_enabled=?,cron=?,timezone=?,next_fire_at=?,config_revision=config_revision+1,updated_by=?,updated_at=current_timestamp where id=?",name,description,state,enabled,cron,zone,enabled?ZonedDateTime.parse(next.getFirst()).toOffsetDateTime():null,actor,id);
  long taskId=id==null?db.queryForObject("select max(id) from sync_tasks",Long.class):id;clearSteps(taskId);var ids=new HashMap<String,Long>();int position=0;
  for(var step:steps){var c=map(step.get("config"));db.update("insert into sync_task_steps(task_id,step_key,position,component_type,name,config_json,secret_bundle_id) values(?,?,?,?,?,?,?)",taskId,step.get("key"),++position,step.get("type"),step.get("name"),encode(c),step.get("secretId"));long stepId=db.queryForObject("select id from sync_task_steps where task_id=? and step_key=?",Long.class,taskId,step.get("key"));ids.put((String)step.get("key"),stepId);if(c.get("serverId")!=null)db.update("insert into sync_step_servers values(?,?)",stepId,id(c,"serverId"));for(var ref:maps(c.get("references")))db.update("insert into sync_step_certificates values(?,?,?,?,?)",stepId,id(ref,"assetId"),id(ref,"materialId"),ref.get("alias"),ref.get("role"));String source=str(c,"sourceStep","");if(!source.isBlank())db.update("insert into sync_step_inputs values(?,?)",stepId,ids.get(source));}
  audit.record(user,"SYNC_TASK_SAVE","SYNC_TASK",taskId);return detail(taskId);
 });}
 private void clearSteps(long id){for(String table:List.of("sync_step_inputs","sync_step_certificates","sync_step_servers"))db.update("delete from "+table+" where step_id in(select id from sync_task_steps where task_id=?)",id);db.update("delete from sync_task_steps where task_id=?",id);}
 public Map<String,Object> validate(long id){var task=stored(id);var steps=maps(task.get("steps"));validator.prepare(steps,true);return Map.of("valid",true,"nextTimes",validator.nextTimes(str(task,"cron",""),str(task,"timezone","")),"entries",steps.stream().filter(s->map(s.get("config")).containsKey("resolvedEntries")).map(s->Map.of("step",s.get("name"),"entries",map(s.get("config")).get("resolvedEntries"))).toList());}
 public void delete(long id,String user){tx.executeWithoutResult(s->{lock();stored(id);require(db.queryForObject("select count(*) from sync_runs where task_id=? and status in('QUEUED','RUNNING')",Integer.class,id)==0,"任务执行中，不能删除");db.update("update sync_tasks set deleted_at=current_timestamp,schedule_enabled=false,next_fire_at=null where id=?",id);audit.record(user,"SYNC_TASK_DELETE","SYNC_TASK",id);});}
 public long enqueue(long taskId,String requestKey,String user){return enqueue(taskId,requestKey,user,null);}
 long enqueue(long taskId,String requestKey,String user,OffsetDateTime scheduled){return tx.execute(s->{lock();var task=stored(taskId);if(requestKey!=null){require(requestKey.length()<=100,"请求标识过长");var prior=db.queryForList("select id from sync_runs where task_id=? and request_key=?",Long.class,taskId,requestKey);if(!prior.isEmpty())return prior.getFirst();}
  require("READY".equals(task.get("state")),"请先校验并保存为可执行任务");require(db.queryForObject("select count(*) from sync_runs where task_id=? and status in('QUEUED','RUNNING')",Integer.class,taskId)==0,"已有执行中的任务，请等待完成");require(db.queryForObject("select count(*) from sync_runs where status='QUEUED'",Integer.class)<100,"等待执行任务过多，请稍后重试");var steps=maps(task.get("steps"));validator.prepare(steps,true);var serverSnapshots=new HashMap<Long,Map<String,Object>>();
  for(var step:steps){var c=map(step.get("config"));if(c.get("serverId")!=null){long server=id(c,"serverId");var snapshot=servers.snapshot(server);serverSnapshots.put(server,snapshot);step.put("serverSnapshot",snapshot);}}task.put("steps",steps);task.put("requestedBy",user==null?"scheduler":user);
  db.update("insert into sync_runs(task_id,trigger_type,scheduled_for,request_key,task_revision,status,snapshot_json) values(?,?,?,?,?,'QUEUED',?)",taskId,scheduled==null?"MANUAL":"SCHEDULED",scheduled,requestKey,task.get("revision"),encode(task));long run=db.queryForObject("select max(id) from sync_runs",Long.class);
  for(var step:steps){if(step.get("secretId")!=null)db.update("merge into sync_run_secret_bundles key(run_id,secret_bundle_id) values(?,?)",run,step.get("secretId"));for(var ref:maps(map(step.get("config")).get("references")))recordCert(run,id(ref,"assetId"),id(ref,"materialId"));}
  for(var snapshot:serverSnapshots.values()){long config=id(snapshot,"configId");db.update("insert into sync_run_servers values(?,?,?)",run,id(snapshot,"id"),config);var secretIds=db.queryForList("select secret_bundle_id from managed_server_configs where id=? and secret_bundle_id is not null",Long.class,config);for(long secret:secretIds)db.update("merge into sync_run_secret_bundles key(run_id,secret_bundle_id) values(?,?)",run,secret);for(var ref:db.queryForList("select source_asset_id,material_id from managed_server_trust_certificates where server_config_id=?",config))recordCert(run,((Number)ref.get("SOURCE_ASSET_ID")).longValue(),((Number)ref.get("MATERIAL_ID")).longValue());}
  int p=0;for(var step:steps)db.update("insert into sync_run_steps(run_id,step_key,position,component_type,name) values(?,?,?,?,?)",run,step.get("key"),++p,step.get("type"),step.get("name"));if(user!=null)audit.record(user,"SYNC_EXECUTE","SYNC_RUN",run);logs.append("SYNC","RUN_QUEUED","INFO",user,run,null,"SYNC_TASK",taskId,"同步任务已入队",Map.of("triggerType",scheduled==null?"MANUAL":"SCHEDULED","revision",task.get("revision")));return run;
 });}
 private void recordCert(long run,long asset,long material){db.update("merge into sync_run_certificates key(run_id,source_asset_id,material_id) values(?,?,?,?)",run,asset,material,db.queryForObject("select fingerprint_sha256 from certificate_materials where id=?",String.class,material));}
 public List<Map<String,Object>> runs(long task){stored(task);return db.query("select * from sync_runs where task_id=? order by id desc fetch first 200 rows only",this::runRow,task);}
 private Map<String,Object> runRow(ResultSet r,int n)throws SQLException{var m=new LinkedHashMap<String,Object>();for(String field:List.of("id","status"))m.put(field,r.getObject(field));m.put("taskId",r.getLong("task_id"));m.put("triggerType",r.getString("trigger_type"));m.put("revision",r.getLong("task_revision"));m.put("errorSummary",r.getString("error_summary"));for(String field:List.of("created_at","started_at","finished_at")){String name=switch(field){case "created_at"->"createdAt";case "started_at"->"startedAt";default->"finishedAt";};m.put(name,r.getObject(field)==null?null:r.getObject(field,OffsetDateTime.class).toString());}return m;}
 public Map<String,Object> runDetail(long id){var rows=db.query("select * from sync_runs where id=?",this::runRow,id);require(!rows.isEmpty(),"执行记录不存在");var run=rows.getFirst();run.put("steps",db.query("select * from sync_run_steps where run_id=? order by position",(r,n)->{var m=new LinkedHashMap<String,Object>();m.put("key",r.getString("step_key"));m.put("name",r.getString("name"));m.put("type",r.getString("component_type"));m.put("status",r.getString("status"));m.put("errorSummary",r.getString("error_summary"));m.put("result",r.getString("result_json")==null?null:decode(r.getString("result_json")));m.put("startedAt",r.getObject("started_at")==null?null:r.getObject("started_at",OffsetDateTime.class).toString());m.put("finishedAt",r.getObject("finished_at")==null?null:r.getObject("finished_at",OffsetDateTime.class).toString());return m;},id));return run;}
 public void schedule(){var due=db.queryForList("select id from sync_tasks where deleted_at is null and schedule_enabled=true and next_fire_at<=current_timestamp");for(var row:due){long id=((Number)row.get("ID")).longValue();OffsetDateTime fire=tx.execute(s->{lock();var current=db.queryForMap("select * from sync_tasks where id=?",id);if(!(Boolean)current.get("SCHEDULE_ENABLED")||current.get("DELETED_AT")!=null||current.get("NEXT_FIRE_AT")==null||((OffsetDateTime)current.get("NEXT_FIRE_AT")).isAfter(OffsetDateTime.now()))return null;var scheduled=(OffsetDateTime)current.get("NEXT_FIRE_AT");var next=CronExpression.parse((String)current.get("CRON")).next(ZonedDateTime.now(ZoneId.of((String)current.get("TIMEZONE"))));db.update("update sync_tasks set next_fire_at=? where id=?",next==null?null:next.toOffsetDateTime(),id);return scheduled;});if(fire==null)continue;try{enqueue(id,null,null,fire);}catch(IllegalArgumentException failure){tx.executeWithoutResult(s->{lock();if(db.queryForObject("select count(*) from sync_runs where task_id=? and scheduled_for=?",Integer.class,id,fire)>0)return;var task=stored(id);db.update("insert into sync_runs(task_id,trigger_type,scheduled_for,task_revision,status,snapshot_json,finished_at,error_summary) values(?,'SCHEDULED',?,?,'FAILED',?,current_timestamp,?)",id,fire,task.get("revision"),encode(Map.of("steps",List.of())),"本次定时执行未入队：任务重叠或当前证书/连接配置不可用");long failedRun=db.queryForObject("select id from sync_runs where task_id=? and scheduled_for=?",Long.class,id,fire);logs.append("SYNC","SCHEDULE_REJECTED","FAILURE","scheduler",failedRun,null,"SYNC_TASK",id,"定时任务未入队：重叠或配置不可用",Map.of());});}}}
}
